function validate(input) {
  const [calls] = input;
  if (!Array.isArray(calls) || calls.length < 1 || calls.length > 10) return 'Give 1 to 10 calls.';
  for (const args of calls) {
    if (!Array.isArray(args) || args.length > 10) return 'Each call is a list of at most 10 arguments.';
    if (args.some(value => value === undefined)) return 'Every argument must be a JSON value.';
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [calls] = input;
  const f = solve();
  if (typeof f !== 'function') throw new Error('createHelloWorld must return a function.');
  const answer = [];
  for (const args of calls) {
    const result = f(...args);
    kit.trace(`f(${args.map(value => JSON.stringify(value)).join(', ')}) returns ${result === undefined ? 'undefined' : JSON.stringify(result)}`);
    answer.push(result === undefined ? null : result);
  }
  return answer;
}

