  const pick = list => list[Math.floor(rand() * list.length)];
  const value = depth => {
    const kind = Math.floor(rand() * (depth > 1 ? 4 : 6));
    if (kind === 0) return Math.floor(rand() * 2001) - 1000;
    if (kind === 1) return pick(['', 'a', 'Hello', 'World', 'hello world', '42']);
    if (kind === 2) return pick([true, false]);
    if (kind === 3) return null;
    const length = Math.floor(rand() * (size === 'small' ? 3 : 6));
    if (kind === 4) return Array.from({ length }, () => value(depth + 1));
    return Object.fromEntries(Array.from({ length }, (_, i) => [`k${i}`, value(depth + 1)]));
  };
  const count = size === 'small' ? 1 + Math.floor(rand() * 4) : 10;
  const calls = [];
  for (let i = 0; i < count; i++) {
    const length = size === 'small' ? Math.floor(rand() * 4) : 10;
